import{_ as i,C as d,o as a,c,j as e,a as r,E as s,b as g,w as o,a3 as h,a4 as A}from"./chunks/framework.D-V5jUSB.js";const v=JSON.parse('{"title":"評測迭代 v1–v8","description":"","frontmatter":{},"headers":[],"relativePath":"eval.md","filePath":"eval.md"}'),E={name:"eval.md"};function b(u,t,m,B,f,C){const n=d("EvalChart"),l=d("Mermaid");return a(),c("div",null,[t[1]||(t[1]=e("h1",{id:"評測迭代-v1–v8",tabindex:"-1"},[r("評測迭代 v1–v8 "),e("a",{class:"header-anchor",href:"#評測迭代-v1–v8","aria-label":'Permalink to "評測迭代 v1–v8"'},"​")],-1)),t[2]||(t[2]=e("p",null,[r("不憑感覺調參:45 條真實查詢的自動評測 harness("),e("strong",null,"LLM-as-judge"),r(" 對每個 query × top-5 結果打相關度),每輪改動都跑分 — 贏的留、輸的回滾。")],-1)),s(n),t[3]||(t[3]=e("h2",{id:"架構-把-config-抽成變數-讓評測自己掃權重",tabindex:"-1"},[r("架構:把 config 抽成變數,讓評測自己掃權重 "),e("a",{class:"header-anchor",href:"#架構-把-config-抽成變數-讓評測自己掃權重","aria-label":'Permalink to "架構:把 config 抽成變數,讓評測自己掃權重"'},"​")],-1)),t[4]||(t[4]=e("p",null,[r("關鍵一招是"),e("strong",null,[r("把搜尋的所有旋鈕從程式碼裡抽出來,變成一份純資料 "),e("code",null,"search-config.json")]),r(" (搜尋熱載,改檔即生效)。一旦 config 是資料而不是寫死的常數,整份 config 就能被當成 一個「變數向量」,讓評測自動 sweep — 這就是 ADR 0004 的兩段式自評閉環。")],-1)),(a(),g(h,null,{default:o(()=>[s(l,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20CFG%5B%22search-config.json%20%E2%80%94%20%E8%A2%AB%E6%8A%BD%E5%87%BA%E7%9A%84%E5%8F%AF%E8%AA%BF%E8%AE%8A%E6%95%B8%22%5D%0A%20%20%20%20%20%20%20%20K%5B%22%E5%85%A8%E5%9F%9F%E6%97%8B%E9%88%95%3Cbr%2F%3Eweights.vector%20%2F%20bm25%20%2F%20hyde%3Cbr%2F%3Errf_k%20%C2%B7%20tag_boost_scale%20%C2%B7%20min_display_score%22%5D%0A%20%20%20%20%20%20%20%20D%5B%2214%20%E7%B6%AD%20dimension%20weights%3Cbr%2F%3Eregion%202.0%20%C2%B7%20ip%201.8%20%C2%B7%20award%201.5%20%E2%80%A6%20curation%200.3%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20QER%5B%22eval-queries.json%3Cbr%2F%3E45%20%E6%A2%9D%E7%9C%9F%E5%AF%A6%E6%9F%A5%E8%A9%A2%20%2B%20qrels%22%5D%0A%0A%20%20%20%20subgraph%20S1%5B%22%E2%91%A0%20Stage%201%20%E2%80%94%20eval_search.py(%E9%87%8F)%22%5D%0A%20%20%20%20%20%20%20%20RUN%5B%22%E8%B7%91%E7%9C%9F%E5%AF%A6%E7%AE%A1%E7%B7%9A%20%E2%86%92%20top-k%22%5D%20--%3E%20JG%5B%22LLM-as-judge%3Cbr%2F%3E%E6%AF%8F%20(query%20%C3%97%20film)%20%E6%89%93%200%20%2F%201%20%2F%202%22%5D%0A%20%20%20%20%20%20%20%20JG%20--%3E%20CA%5B(%22judge%20cache%3Cbr%2F%3Eper%20query%C3%97film%22)%5D%0A%20%20%20%20%20%20%20%20JG%20--%3E%20RX%5B%22ranx%3Cbr%2F%3EnDCG%40k%20%C2%B7%20MAP%20%C2%B7%20MRR%20%C2%B7%20P%40k%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20S2%5B%22%E2%91%A1%20Stage%202%20%E2%80%94%20tune_search.py(%E6%8E%83)%22%5D%0A%20%20%20%20%20%20%20%20SAMP%5B%22random-search%20%E5%8F%96%E6%A8%A3%20SPACE%22%5D%20--%3E%20APPLY%5B%22_apply%20combo%20%E2%86%92%20cfg%22%5D%0A%20%20%20%20%20%20%20%20APPLY%20--%3E%20INJ%5B%22_inject%20%E7%86%B1%E6%9B%BF%E6%8F%9B%20config%3Cbr%2F%3E(%E4%B8%8D%E5%AF%AB%E7%A3%81%E7%A2%9F)%22%5D%0A%20%20%20%20%20%20%20%20RX%20--%3E%20SCORE%5B%22score%20%3D%20nDCG%40k%22%5D%0A%20%20%20%20%20%20%20%20SCORE%20--%3E%20CMP%7B%22best%20%3E%20baseline%3F%22%7D%0A%20%20%20%20end%0A%0A%20%20%20%20QER%20--%3E%20RUN%0A%20%20%20%20CFG%20-.%20%E6%8A%BD%E6%88%90%E8%AE%8A%E6%95%B8%20.-%3E%20SAMP%0A%20%20%20%20INJ%20--%3E%20RUN%0A%20%20%20%20CMP%20--%3E%7C%E6%98%AF%7C%20CAND%5B%22candidate.json%20%2B%20%E6%AF%94%E8%BC%83%E5%A0%B1%E5%91%8A%22%5D%0A%20%20%20%20CMP%20--%3E%7C%E5%90%A6%7C%20KEEP%5B%22%E4%BF%9D%E7%95%99%E7%8F%BE%E8%A1%8C%20config%22%5D%0A%20%20%20%20CAND%20--%3E%20PRO%5B%22%E2%91%A2%20Stage%203%20%E2%80%94%20%E4%BA%BA%E5%B7%A5%20promote%22%5D%0A%0A%20%20%20%20classDef%20llm%20fill%3A%23f26f21%2Cstroke%3A%23d4570c%2Ccolor%3A%23000%0A%20%20%20%20classDef%20store%20fill%3A%231f1f1f%2Cstroke%3A%23f26f21%2Ccolor%3A%23efefef%0A%20%20%20%20class%20JG%20llm%0A%20%20%20%20class%20CA%2CCAND%20store%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[r(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=A('<h3 id="抽出的是哪些變數權重" tabindex="-1">抽出的是哪些變數權重 <a class="header-anchor" href="#抽出的是哪些變數權重" aria-label="Permalink to &quot;抽出的是哪些變數權重&quot;">​</a></h3><p>config 抽出後分兩層,各自用不同方式定權重:</p><table tabindex="0"><thead><tr><th>層</th><th>變數</th><th>怎麼定</th></tr></thead><tbody><tr><td><strong>全域旋鈕</strong>(SPACE)</td><td><code>weights.vector/bm25/hyde</code>(三路召回權重)、<code>tag_boost_scale</code>(維度 boost 總倍率)、<code>rrf_k</code>(融合常數)、<code>min_display_score</code></td><td>Stage 2 <strong>random-search 自動掃</strong> — 對 SPACE 做笛卡兒積、隨機取樣 N 組</td></tr><tr><td><strong>14 維 dimension weights</strong></td><td>region 2.0 · ip 1.8 · award/audience 1.5 · genre 1.0 · theme 0.7 … curation 0.3</td><td><strong>手調</strong>,判準:越定義性/事實性(地區/IP/得獎)權重越高、偏好性(主題/情緒)越低</td></tr></tbody></table><p>權重不是篩子是加分:統一「加權 boost」模型,<strong>沒有任何硬性過濾</strong> —— 每部片帶到查詢要求的 tag,分數 <code>+= 該維 weight × tag_boost_scale</code>,所以永不清空結果。weight ≥ <code>inject_weight_threshold</code> (1.5)的維度算「強條件」,會主動把帶該 tag 的片<strong>注入</strong>候選池(就是搜尋頁說的「外卡」), 確保有結果可排,而不是只靠召回撞到。</p><h3 id="為什麼掃得起-judge-cache" tabindex="-1">為什麼掃得起:judge cache <a class="header-anchor" href="#為什麼掃得起-judge-cache" aria-label="Permalink to &quot;為什麼掃得起:judge cache&quot;">​</a></h3><p>掃 N 組 config 看似要判 N 次,但<strong>相關度是 per (query, film),跟 config 無關</strong> —— 換一組權重只是把同一批片<strong>重新排序</strong>,並沒有產生新的 (query, film) 配對。所以判過的結果 全部命中 <code>judge cache</code>,N 組 config 幾乎只付<strong>一次</strong> judge 成本(最貴的那筆)。 這就是「把 config 抽成變數來掃」能成立的前提。</p><p>評分時用 <code>rerank=False</code>(關掉 CE 精排):排除精排噪音、純看召回 + 權重排序本身的貢獻, 而且快。最後<strong>不覆寫線上 config</strong> — 贏家只寫進 <code>candidate.json</code> + 比較報告, 由人(Stage 3)決定要不要 promote → 呼應<a href="/film-brain/vp-preview/self-eval">自評閉環</a>的「贏留、輸回滾」與人在迴圈。</p><h2 id="名詞解釋" tabindex="-1">名詞解釋 <a class="header-anchor" href="#名詞解釋" aria-label="Permalink to &quot;名詞解釋&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指標</th><th>白話</th><th>1.0 的意思</th></tr></thead><tbody><tr><td><strong>nDCG@5</strong></td><td>前 5 名的「排序品質」— 對的片排得越前面分數越高,排對位置比只是有出現更重要</td><td>理想排序:最相關的剛好都排最前</td></tr><tr><td><strong>MRR</strong></td><td>第一個相關結果平均出現在第幾名(取倒數)— 衡量「第一名直接就對」的能力</td><td>每一條查詢的第 1 名都相關</td></tr><tr><td><strong>P@5</strong></td><td>前 5 名裡相關影片的比例 — 不管順序,只看命中率</td><td>前 5 名全部相關</td></tr></tbody></table><h2 id="各版本一覽" tabindex="-1">各版本一覽 <a class="header-anchor" href="#各版本一覽" aria-label="Permalink to &quot;各版本一覽&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>改了什麼</th><th>nDCG@5</th><th>MRR</th><th>P@5</th><th>結論</th></tr></thead><tbody><tr><td>v1</td><td>baseline(hybrid + RRF)</td><td>0.9307</td><td>0.925</td><td>0.86</td><td>起點</td></tr><tr><td>v2</td><td>多項 gating 一起上</td><td>0.9255</td><td>0.9167</td><td>0.84</td><td>回退 — 一次改太多</td></tr><tr><td><strong>v3</strong></td><td>只留 parser alias</td><td><strong>0.9512</strong></td><td>0.925</td><td><strong>0.89</strong></td><td>第一個大贏</td></tr><tr><td>v4</td><td>+ 英文域 reranker</td><td>0.9368</td><td>0.925</td><td>0.73</td><td>選錯模型,精確度掉</td></tr><tr><td>v5</td><td>step-back 全開</td><td>0.9350</td><td>0.925</td><td>0.85</td><td>幫模糊查詢、傷具體查詢</td></tr><tr><td><strong>v6</strong></td><td>step-back 改條件觸發</td><td>0.9623</td><td><strong>1.000</strong></td><td>0.84</td><td>MRR 滿分 ⭐</td></tr><tr><td>v7</td><td>再試英文域 reranker</td><td>0.9368</td><td>0.9417</td><td>0.79</td><td>確認是模型問題</td></tr><tr><td><strong>v8</strong></td><td>換中文域 reranker(bce)</td><td><strong>0.9625</strong></td><td>0.975</td><td><strong>0.89</strong></td><td>均衡最佳 ⭐</td></tr></tbody></table><h2 id="迭代手記-—-每一版在想什麼" tabindex="-1">迭代手記 — 每一版在想什麼 <a class="header-anchor" href="#迭代手記-—-每一版在想什麼" aria-label="Permalink to &quot;迭代手記 — 每一版在想什麼&quot;">​</a></h2><details class="note"><summary>v1 — 先量再動</summary> 動手調參前先立尺:雙路召回 + RRF + 加權 boost 的素管線直接跑分,0.9307。沒有 baseline 的優化都是自我感覺良好。 </details><details class="note"><summary>v2 — 貪心:四個想法一起上,整體回退</summary> 當時覺得 query 理解有四個明顯可改(關鍵字對照表、展開降權、維度過濾、跳過展開),都對就全上。結果 -0.005:3 條變好、5 條變差,而且互相打架,根本分不出誰的功勞誰的鍋。<br><b class="turn">→ 轉折:從此一輪只動一個變因。這個紀律比任何單一技巧值錢。</b></details><details class="note"><summary>v3 — 拆開重來,只留一個:第一個大贏</summary> 把 v2 四件事拆開,只留「關鍵字對照表」(英文別名 + 50 個中文類型詞 + 得獎詞)。+0.02 → 0.9512,「韓國犯罪驚悚」「得獎」「監獄」這些之前完全漏接的訊號全接住了。<br><b class="turn">→ 學到:擴充對照表是純賺,沒有副作用,值得一直補。</b></details><details class="note"><summary>v4 — 第一次上精排模型:翻車</summary> 直覺上「多一層精排一定更準」。掛上英文域訓練的 reranker,反而 -0.014,前五命中率掉到 0.73。<br><b class="turn">→ 學到:它是在英文資料上學的「相關」,看不懂中文片庫;「多一層 AI」不保證更好。</b></details><details class="note"><summary>v5 — 抽象化查詢:幫了模糊的,傷了具體的</summary> 讓 LLM 把查詢「抽象化」(「被仙人跳分手療傷」→「失戀療癒」)再多召回一路。模糊查詢 +1,但 6 條具體查詢(「香港警匪片」「監獄」…)被拉進雜訊,淨輸。<br><b class="turn">→ 轉折:這招是雙面刃,問題不是「要不要用」,是「什麼時候用」。</b></details><details class="note"><summary>v6 — 同一招,加個開關:MRR 滿分 ⭐</summary> 只在「查詢裡抓不到任何具體條件」時才啟用抽象化。0.9623,每一條查詢的第一名都對(MRR 1.0)。<br><b class="turn">→ 學到:v2 教訓真正的形狀 — gating 不是不能做,是要鎖在最小的那顆旋鈕上。</b></details><details class="note"><summary>v7 — 不死心再試英文 reranker:確認是模型的鍋</summary> 給它補上年份/地區/卡司資訊、改成位置感知混分 — 架構上全對,分數還是 0.9368。<br><b class="turn">→ 學到:架構修補救不了選錯模型。兩輪失敗把問題定位釘死了。</b></details><details class="note"><summary>v8 — 換中文域 reranker:均衡最佳 ⭐</summary> 同一個 API 介面,換成中文 IR 訓練的 bce 模型。nDCG 持平 0.9625,但前五命中率 +0.05、評測零失敗 — 精排終於開始賺錢。<br><b class="turn">→ 學到:reranker 的語言域比架構重要;對的模型讓 v4/v7 全部的架構工作瞬間生效。</b></details><h2 id="幾個有代表性的教訓" tabindex="-1">幾個有代表性的教訓 <a class="header-anchor" href="#幾個有代表性的教訓" aria-label="Permalink to &quot;幾個有代表性的教訓&quot;">​</a></h2><ul><li><strong>一次只改一件事</strong> — v2 把四個想法一起上,整體回退;v3 拆開只留一個,+0.02。</li><li><strong>step-back 抽象查詢向量是雙面刃</strong> — 模糊查詢(「被仙人跳分手療傷」)受益,具體查詢(「香港警匪片」)被拉進雜訊;v6 改成「parser 抓不到具體條件才啟用」後 MRR 1.0。</li><li><strong>reranker 的語言域比架構重要</strong> — 同 API 介面,英文域模型連兩輪扣分,換中文域訓練的 bce 立刻 nDCG +0.026、P@5 +0.10。</li></ul><h2 id="附註-換一把更省電的尺-—-judge-的模型與硬體" tabindex="-1">附註:換一把更省電的尺 — judge 的模型與硬體 <a class="header-anchor" href="#附註-換一把更省電的尺-—-judge-的模型與硬體" aria-label="Permalink to &quot;附註:換一把更省電的尺 — judge 的模型與硬體&quot;">​</a></h2><p>評測的打分者(LLM judge)<strong>全程都是本地模型</strong>。為什麼不用雲端?一輪評測是 45 條查詢 × top-5 = 最多 225 次打分,11 輪迭代下來逼近 2,500 次 — 走雲端免費額度馬上撞限流,還會跟產品本身的 LLM 配額互搶;本地 judge 零邊際成本、隨時重跑、結果可重現(同模型同 prompt,分數不會因服務端改版而漂)。</p><p>v1–v8 用較大的 MoE 模型(35B-A3B,跑在 GPU);後來換成小一號的 <strong>8B dense 模型跑在 NPU</strong> 重評 —<strong>模型不同 = 尺不同,分數不能跟上面直接比</strong>,所以分開列:</p><table tabindex="0"><thead><tr><th>輪次</th><th>範圍</th><th>nDCG@5</th><th>MRR</th><th>結論</th></tr></thead><tbody><tr><td>8B judge @ NPU(子集)</td><td>20 條查詢</td><td>0.9286</td><td>0.9417</td><td>小模型 + NPU 評測管線跑通</td></tr><tr><td>8B judge @ NPU(全量)</td><td>45 條查詢</td><td>0.9233</td><td>0.9444</td><td>持續穩定 — 評測可低功耗長跑,不佔 GPU</td></tr></tbody></table>',26))])}const D=i(E,[["render",b]]);export{v as __pageData,D as default};
